import {savedWritingText} from './writing-studio.js?v=20261017-files1';
import {dailyLearning,dailyLearningHTML} from './daily-learning.js?v=20261015-books1';
import {checkGrammar} from './grammar.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let options={},owner='',saved={},busy=new Set(),contexts=new Map(),generation=0,taskData=null,taskError='',taskFlight=null,taskLoaded=0;
function sync(){const id=options.studentId?.()||'';if(id===owner)return;owner=id;generation++;saved={};busy=new Set();contexts=new Map();taskData=null;taskError='';taskFlight=null;taskLoaded=0;if(owner)try{saved=JSON.parse(localStorage.getItem('richmount-writing-coach:'+owner)||'{}');}catch{}}
function persist(){if(owner)try{localStorage.setItem('richmount-writing-coach:'+owner,JSON.stringify(saved));}catch{options.toast?.('The review could not save on this device. Keep this page open.');}}
export function markedWriting(text,annotations=[]){let at=0,out='';for(const a of [...annotations].sort((a,b)=>a.start-b.start)){if(!Number.isInteger(a.start)||!Number.isInteger(a.end)||a.start<at||a.end<=a.start||a.end>text.length)continue;out+=esc(text.slice(at,a.start))+`<mark class="writing-mark" title="${esc(a.category+': '+a.explanation)}">${esc(text.slice(a.start,a.end))}</mark>`;at=a.end;}return out+esc(text.slice(at));}
export function basicWritingReport(text){const result=checkGrammar(text);return {source:'basic',bandEstimate:null,summary:'Basic draft checks: review these patterns and make your own changes. These rules may miss mistakes.',strengths:[],nextSteps:result.notes,criteria:[],annotations:result.issues.map(a=>({...a,quote:a.original,explanation:a.message,hint:'Check the '+a.category.toLowerCase()+' rule here. Read the sentence aloud and revise it in your own words.'}))};}
export function writingFeedbackHTML(report,text,{teacher=false}={}){return `<section class="writing-feedback"><div class="section-head"><h3>${report.source==='ai'?'AI writing guidance':'Basic draft checks'}</h3><span class="pill">${report.bandEstimate!=null?'Practice band ≈ '+report.bandEstimate.toFixed(1):'Feedback only'}</span></div><p>${esc(report.summary)}</p><p class="small muted">${report.source==='ai'?'Approximate practice assessment; your teacher can review it. This is not an official IELTS score.':'Offline rules, not AI. They do not assess your argument or assign a band.'}</p><h4>Your reviewed draft</h4><div class="corrected-text marked-writing">${markedWriting(text,report.annotations)}</div>${report.annotations?.length?`<ol class="writing-hints">${report.annotations.map(a=>`<li><span class="pill">${esc(a.category)}</span> <strong>“${esc(a.quote)}”</strong><p>${esc(a.explanation)}</p><p class="small"><strong>Try this:</strong> ${esc(a.hint)}</p>${teacher&&a.teacherSuggestion?`<p class="teacher-comment">Possible correction: ${esc(a.teacherSuggestion)}</p>`:''}</li>`).join('')}</ol>`:'<p class="small muted">No specific passages were marked. Continue checking task coverage and meaning.</p>'}${report.strengths?.length?`<h4>What is working</h4><ul>${report.strengths.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}${report.nextSteps?.length?`<h4>Your next revision</h4><ol>${report.nextSteps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:''}${report.criteria?.length?`<div class="table-wrap"><table><caption>Writing practice matrix · goal: band 8–9</caption><thead><tr><th>Criterion</th><th>Estimate</th><th>Next step</th></tr></thead><tbody>${report.criteria.map(c=>`<tr><th>${esc(c.name)}</th><td>${c.band==null?'—':c.band.toFixed(1)}</td><td>${esc(c.reason)}<br><strong>${esc(c.nextStep)}</strong></td></tr>`).join('')}</tbody></table></div>`:''}${report.scoreNote?`<p class="small muted">${esc(report.scoreNote)}</p>`:''}<p class="small muted">Rewrite in your editor using your own ideas. Check that your revision keeps the meaning you intended.</p></section>`;}
export function coachHTML(key,selector,text,inputId){sync();contexts.set(key,{selector,text,inputId});const item=saved[key];return `<section class="coach-panel" data-coach-panel="${esc(key)}"><p class="small muted">AI feedback uses Gemini. Use this adult-only feature with writing that contains no personal or confidential information. Google may use free-tier inputs and outputs to improve products and for human review. Basic draft checks stay on your device.</p><div class="button-row"><button type="button" class="button soft" data-coach-action="ai" data-coach-key="${esc(key)}" ${busy.has(key)?'disabled':''}>${busy.has(key)?'Reviewing your draft…':item?'Review my revision with AI':'Check my draft with AI'}</button><button type="button" class="button secondary" data-coach-action="basic" data-coach-key="${esc(key)}" ${busy.has(key)?'disabled':''}>Basic draft checks</button></div><p class="small muted">AI coaching becomes available when your teacher activates it. Your writing and task are sent securely to the AI provider for review.</p>${item?.error?`<p class="notice warm" role="alert">${esc(item.error)}</p>`:''}${item?.report?writingFeedbackHTML(item.report,item.text):''}</section>`;}
export function coachRevision(key,original){sync();return savedWritingText(key,saved[key]?.draft??original);}
export function coachReportId(key,text){sync();const item=saved[key];return item?.report?.source==='ai'&&item.text===text?item.report.id:null;}
export function finalWritingConfirmation(){return `<label class="check-item final-writing-confirm"><input type="checkbox" data-writing-confident>I have reviewed my writing and I’m confident it represents my own ideas.</label>`;}
export function writingProgressHTML(records=[]){const selected=records.filter(r=>r.kind==='writing').map(r=>{const mark=r.reviewed&&/^\s*(?:band\s*)?(\d(?:\.\d)?)\s*$/i.exec(r.teacher_score||''),teacher=mark?Number(mark[1]):null,ai=typeof r.ai_band==='number'?r.ai_band:null;return {...r,teacher:teacher!=null&&teacher<=9?teacher:null,ai};}).filter(r=>r.teacher!==null||r.ai!==null).sort((a,b)=>a.created_at.localeCompare(b.created_at)).slice(-30);
 if(!selected.length)return '<section class="card band-progress"><h3>Your journey toward band 8–9</h3><p>Practice Writing estimates and teacher-reviewed bands will appear here after scored responses. Classroom paragraph exercises get guidance without a band.</p></section>';
 const width=760,height=240,left=40,bottom=208,span=selected.length>1?660/(selected.length-1):0,x=i=>left+(span?i*span:330),y=n=>bottom-n/9*174;
 const dots=selected.flatMap((r,i)=>[[r.ai,'#a96920','AI estimate'],[r.teacher,'#216c58','Teacher reviewed']].filter(([n])=>n!==null).map(([n,color,label])=>`<circle cx="${x(i)}" cy="${y(n)}" r="5" fill="${color}"><title>${esc(label+' · '+r.title+' · '+n+' · '+r.created_at.slice(0,10))}</title></circle>`)).join('');
 const paths=[...new Set(selected.map(r=>r.writing_task_type||'teacher-assessed'))].flatMap(type=>[['ai','#a96920'],['teacher','#216c58']].map(([key,color])=>{const points=selected.map((r,i)=>r[key]===null||(r.writing_task_type||'teacher-assessed')!==type?null:`${x(i)},${y(r[key])}`).filter(Boolean);return points.length>1?`<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="2" stroke-dasharray="${key==='ai'?'5 4':'0'}"/>`:'';})).join('');
 return `<section class="card band-progress"><h3>Your Writing progress · goal: band 8–9</h3><p class="small muted">Gold: AI practice estimates · Green: teacher reviewed. Task 1 and Task 2 remain separate in the matrix. These are Writing practice assessments, not overall IELTS scores.</p><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Writing band progress toward band 8 to 9"><rect x="40" y="${y(9)}" width="680" height="${y(8)-y(9)}" fill="#e9f3d7"/>${[0,2,4,6,8,9].map(n=>`<line x1="40" y1="${y(n)}" x2="720" y2="${y(n)}" stroke="#d8e3db"/><text x="16" y="${y(n)+4}" font-size="12">${n}</text>`).join('')}${paths}${dots}<text x="40" y="230" font-size="12">Earlier writing</text><text x="640" y="230" font-size="12">Latest writing</text></svg><div class="table-wrap"><table><caption>Your practice matrix</caption><thead><tr><th>Writing activity</th><th>Task</th><th>AI estimate</th><th>Teacher band</th></tr></thead><tbody>${selected.slice().reverse().map(r=>`<tr><th>${esc(r.title)}<small>${esc(r.created_at.slice(0,10))}</small></th><td>${esc(r.writing_task_type||'Teacher assessment')}</td><td>${r.ai===null?'—':r.ai.toFixed(1)}</td><td>${r.teacher===null?'—':r.teacher.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></section>`;
}
export function studentNotificationState(){sync();const teacher=!!options.isTeacher?.();if(teacher||!owner)return {teacher,owner:teacher?'':owner,loaded:false,loading:false,error:'',tasks:[],feedback:0};
 const today=new Date().toISOString().slice(0,10),tasks=(taskData?.activities||[]).filter(a=>a.published!==false&&/^[a-zA-Z0-9_-]+$/.test(a.id)).map(a=>{const rows=(taskData.submissions||[]).filter(r=>r.activity_id===a.id);const audioNeeded=(a.kind==='speaking'&&!rows.some(r=>r.recordings>0))||(a.type==='mock'&&rows.length&&!rows.some(r=>r.kind==='speaking'&&r.recordings>0));return {...a,needed:!rows.length||a.type==='mock'&&new Set(rows.map(r=>r.kind==='writing'?r.section:r.kind)).size<5||audioNeeded,label:audioNeeded?'Recording needed':a.dueDate&&a.dueDate<today?'Overdue':'To do'};}).filter(a=>a.needed).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')||a.week-b.week);
 const aiFeedback=0; // Published teacher feedback already has its own notification; private AI drafts never notify students.
 const weekly=taskData?.weekly,window=weekly?.window,feedback=(taskData?.submissions||[]).filter(r=>r.reviewed&&(r.feedback||r.feedback_file_count>0)&&(!window||(r.weekly_key?r.weekly_key===window.key:r.created_at>=window.startsAt&&r.created_at<window.endsAt))).length;
 return {teacher,owner,loaded:!!taskData,loading:!!taskFlight,error:taskError,tasks:weekly?(window.active?weekly.tasks.filter(task=>task.needed):[]):tasks,feedback,aiFeedback,weekly,daily:dailyLearning(owner,options.studentName?.(),options.now?.()??Date.now())};
}
export function studentDailyLearningHTML(){return dailyLearningHTML(studentNotificationState().daily);}
export function studentTaskBarHTML(){if(options.isTeacher?.())return '';sync();if(!owner)return `<aside class="student-task-bar"><strong>Your homework & activities</strong><a href="#class">Join your class to see what needs doing →</a></aside>`;
 if(!taskData)return `<aside class="student-task-bar" role="status"><strong>Your homework & activities</strong><span>${esc(taskError||'Checking your class activities…')}</span><button class="button secondary" data-coach-action="refresh-tasks">Refresh</button></aside>`;
 const {tasks,feedback,weekly}=studentNotificationState();
 if(weekly)return `<aside class="student-task-bar" aria-label="This week’s deliverables">${taskError?`<p role="alert">${esc(taskError)} · Last loaded list is shown.</p>`:''}<div><strong>Week ${weekly.window.week} · ${weekly.window.active?(tasks.length?tasks.length+' deliverables to do':weekly.tasks.length?'Your to-do list is complete. Nice work!':'No shared deliverables this week yet'):'Starts '+esc(weekly.window.startDate)}</strong><span>${weekly.standing.points} approved points${weekly.awaitingApproval?' · '+weekly.awaitingApproval+' awaiting teacher approval':''}</span></div>${tasks.map(task=>`<a class="task-notice" href="${esc(task.href)}"><span class="pill">${esc(task.status)}</span><span>${esc(task.title)} →</span></a>`).join('')}<a class="button soft" href="#deliverables">This week’s list & standing →</a><button class="button secondary" data-coach-action="refresh-tasks">Refresh</button></aside>`;
 return `<aside class="student-task-bar" aria-label="Homework notifications">${taskError?`<p role="alert">${esc(taskError)} · Last loaded activities are shown.</p>`:''}<div><strong>${tasks.length?tasks.length+' activities need your attention':'Your shared activities are complete. Nice work!'}</strong>${feedback?`<a href="#progress">${feedback} teacher feedback ${feedback===1?'item':'items'} →</a>`:''}</div>${tasks.slice(0,3).map(a=>`<a class="task-notice" href="#course/${esc(a.id)}"><span class="pill">${esc(a.label)}${a.dueDate?' · Due '+esc(a.dueDate):''}</span><span>${esc(a.title)} →</span></a>`).join('')}<details><summary>View all tasks (${tasks.length})</summary>${tasks.map(a=>`<p><a href="#course/${esc(a.id)}">${esc(a.title)} · ${esc(a.label)}${a.dueDate?' · '+esc(a.dueDate):''} →</a>${a.message?`<br><small>${esc(a.message)}</small>`:''}</p>`).join('')||'<p>No pending shared activities.</p>'}</details><button class="button secondary" data-coach-action="refresh-tasks">Refresh</button></aside>`;
}
export async function refreshStudentTasks(force=false){sync();const window=taskData?.weekly?.window;if(window&&(Date.now()>=Date.parse(window.endsAt)||!window.active&&Date.now()>=Date.parse(window.startsAt)))force=true;if(options.isTeacher?.()||!owner||taskFlight||!force&&Date.now()-taskLoaded<60000)return;const version=generation,id=owner;taskFlight=options.request('/api/student/course').then(data=>{if(version===generation&&id===owner){taskData=data;taskError='';taskLoaded=Date.now();}}).catch(e=>{if(version===generation){taskError=e.message;taskLoaded=Date.now();}}).finally(()=>{if(version===generation){taskFlight=null;(options.onTasksChanged||options.render)?.();}});return taskFlight;}
export function coachingConnectionChanged(){sync();taskLoaded=0;void refreshStudentTasks(true);}
export function initCoaching(callbacks){options=callbacks;document.addEventListener('input',e=>{const key=e.target.dataset.coachRevision;if(key){sync();saved[key]={...saved[key],draft:e.target.value};persist();}});document.addEventListener('click',async e=>{const button=e.target.closest('[data-coach-action]');if(!button||button.disabled)return;const action=button.dataset.coachAction;if(action==='refresh-tasks'){taskLoaded=0;await refreshStudentTasks(true);return;}sync();const key=button.dataset.coachKey,context=contexts.get(key);if(!context||busy.has(key))return;const text=document.getElementById(context.inputId)?.value??context.text;if(!text.trim()){options.toast?.('Write your response before checking it.');return;}const id=owner,version=generation;if(action==='basic'){saved[key]={text,report:basicWritingReport(text)};persist();options.render?.();return;}if(!owner){options.toast?.('Join your class to use AI writing coaching.');return;}saved[key]={...saved[key],draft:text};persist();busy.add(key);options.render?.();try{const result=await options.request('/api/student/writing-review',{method:'POST',body:JSON.stringify({selector:context.selector,text}),ai:true});if(version===generation&&id===owner){saved[key]={text,draft:text,report:result.report};persist();if(context.selector.submissionId)await options.refresh?.();}}catch(error){if(version===generation&&id===owner){saved[key]={...saved[key],error:error.message};persist();}}finally{if(version===generation){busy.delete(key);options.render?.();}}});}
